#ifdef USE_CLEARCOAT_INTENSITY
    _surface.clearCoat *= vfx_commonprofile.clearCoatIntensity;
#endif
#elif defined(USE_CLEARCOAT_COLOR)
    _surface.clearCoat = vfx_commonprofile.clearCoat;
